quote:
			}
			if filterPort != 0 && !podInfo.declaresPort(container.Name, filterPort) {
				continue
			}
			for _, svc := range getServiceNameFromPod(podInfo, *c.k8sServices.Load(), lrcConfig) {
				generatedKey := fmt.Sprintf("%s/%s/%s/%s", svc, podInfo.NodeName, podInfo.Name, container.Name)
				podsInKubernetesLocal[generatedKey] = true
			}
		}

		return true
	})

	// De-registering v3.1 endpoints.
	// Collect stale serviceIDs in a set so we delete from addedPods only once per
	// serviceID after the range completes, avoiding a race where eventAddFunc
	// re-registers a pod between successive calls for the same serviceID.
	staleServiceIDs := make(map[string]bool)
	c.addedEndpointsPrimary.Range(func(key any, value any) bool {
		endpointKey, ok := key.(string)
		if !ok {
			log.Error().Dict("custom_attributes", logger.Attrs().
				Str("status_code", string(logger.GALACTUS_CLEAN_KEY_PARSE_FAILED)).
				Str("runId", uuid).
				Interface("key", key)).
				Msg(logger.Msg(logger.GALACTUS_CLEAN_KEY_PARSE_FAILED))
			return true
		}
		serviceID, err := utils.KeyToServiceID(endpointKey)
		if err != nil {
			log.Error().Dict("custom_attributes", logger.Attrs().
				Str("status_code", string(logger.GALACTUS_CLEAN_KEY_PARSE_FAILED)).
				Str("runId", uuid).
				Str("endpoint_key", endpointKey).
				Str("error", err.Error())).
				Msg(logger.Msg(logger.GALACTUS_CLEAN_KEY_PARSE_FAILED))
			return true
		}
		if _, ok := podsInKubernetesLocal[serviceID]; ok {
			return true
		}

		if err := c.adapterPrimary.Delete(endpointKey); err != nil {
			log.Error().Dict("custom_attributes", logger.Attrs().
				Str("status_code", string(logger.GALACTUS_CLEAN_STALE_FAILED)).
				Str("runId", uuid).
				Str("endpoint_key", endpointKey).
				Str("error", err.Error())).
				Msg(logger.Msg(logger.GALACTUS_CLEAN_STALE_FAILED))
			return true
		}
		staleServiceIDs[serviceID] = true
		parts := strings.Split(serviceID, "/")
		if len(parts) < 3 {
			log.Error().Dict("custom_attributes", logger.Attrs().
				Str("status_code", string(logger.GALACTUS_CLEAN_KEY_PARSE_FAILED)).
				Str("runId", uuid).
				Str("serviceID", serviceID)).
				Msg("CleanFunc: unexpected serviceID format")
			return true
		}
		podName := parts[2]
		svc := parts[0]
		log.Info().Dict("custom_attributes", logger.Attrs().
			Str("status_code", string(logger.GALACTUS_CLEAN_STALE_REMOVED)).
			Str("runId", uuid).
			Str("pod_name", podName).
			Str("service", svc)).
			Msg(logger.Msg(logger.GALACTUS_CLEAN_STALE_REMOVED))
		metrics.DeletePodRegisterStatus(podName)
		log.Debug().Dict("custom_attributes", logger.Attrs().
			Str("runId", uuid).
			Str("serviceID", serviceID)).
			Msg("CleanFunc: endpoint deleted from etcd and addedPods")
		metrics.CleanFuncCleanEndpointCounter.WithLabelValues("clean", svc).Inc()
		return true
	})
	// Clean up addedPods once per stale serviceID after all etcd keys are deleted
	for serviceID := range staleServiceIDs {
		c.addedPods.Delete(serviceID)
		c.addedPodsMu.Delete(serviceID)
	}

	// Branch B (per-IP orphan reconcile): the loop above (Branch A) reaps
	// endpoints whose POD is gone. It does NOT catch the CAST spot-VM in-place
	// reboot case, where the pod keeps its name+UID but gets a NEW IP with no
	// pod-delete event — the pod still exists so Branch A skips it, leaving a
	// permanent dead-IP endpoint. Branch B deletes any endpoint key whose IP is
	// no longer in its owning pod's current PodIPs. It runs independently against
	// each entity etcd and is gated by ORPHAN_RECONCILE_MODE.
	c.reconcileStaleIPEndpoints(uuid, podsInKubernetesLocal)

	return nil
}

// normaliseOrphanReconcileMode maps an arbitrary env value to one of the three
// valid Branch B modes, defaulting to shadow for anything unrecognised so a
// typo can never silently enable deletes.
func normaliseOrphanReconcileMode(mode string) string {
	switch strings.ToLower(strings.TrimSpace(mode)) {
	case utils.OrphanReconcileModeOff:
		return utils.OrphanReconcileModeOff
	case utils.OrphanReconcileModeEnforce:
		return utils.OrphanReconcileModeEnforce
	case utils.OrphanReconcileModeShadow:
		return utils.OrphanReconcileModeShadow
	default:
		return utils.OrphanReconcileModeShadow
	}
}

// Branch B orphan reasons (metric label values).
const (
	orphanReasonIPMismatch  = "ip_mismatch"
	orphanReasonUIDMismatch = "uid_mismatch"
	// orphanReasonPodTerminal covers a pod that still exists in the API but has
	// reached a terminal phase (Failed/Succeeded) while an endpoint for it is
	// still registered. Branch A cannot reap these — the pod object is present,
	// so its serviceID is in podsInKubernetesLocal and the key is treated as
	// live — and neither existing Branch B arm fires either, because an evicted
	// pod keeps both its Status.PodIP (IP still matches) and its UID.
	orphanReasonPodTerminal = "pod_terminal"
)

// FlushOrphanReconcileState clears the leader-local two-pass firstSeenStale map.
// Called on every leadership change so a newly-promoted leader starts its
// two-pass grace from scratch and never deletes on the strength of a stale
// observation made by a previous leader (or a previous term of this pod).
func (c *Controller) FlushOrphanReconcileState() {
	c.firstSeenStaleMu.Lock()
	c.firstSeenStale = make(map[string]time.Time)
	c.firstSeenStaleMu.Unlock()
}

// reconcileStaleIPEndpoints is Clean() Branch B. It scans the registered
// endpoint keys of each entity etcd and deletes (in enforce mode) any key whose
// IP is no longer present in its owning pod's current Status.PodIPs, subject to
// a two-pass grace, a per-pass safety fuse, and a mode kill-switch.
//
// INVARIANT (pod-scoped, do NOT change): the predicate ONLY compares a key's IP
// against the PodIPs of THAT key's own pod (identified by the key's
// service/node/pod/container serviceID). It MUST NEVER implement a cluster-wide
// "is this IP live on some pod" check — pod IPs are not unique across time or
// across nodes, so a cluster-wide check would delete a legitimately-live
// endpoint whose IP happens to be reused elsewhere.
func (c *Controller) reconcileStaleIPEndpoints(runID string, podsInKubernetesLocal map[string]bool) {
	if c.orphanReconcileMode == utils.OrphanReconcileModeOff {
		log.Debug().Str("runId", runID).Msg("CleanFunc[BranchB]: ORPHAN_RECONCILE_MODE=off, skipping per-IP reconcile")
		return
	}

	// Pod IP source = the informer/lister cache (spec requirement: no direct API
	// Gets). Gate on HasSynced so we never act on a cold cache.
	if c.podInformer == nil || !c.podInformer.HasSynced() {
		log.Warn().Str("runId", runID).Msg("CleanFunc[BranchB]: pod informer not synced, skipping per-IP reconcile")
		return
	}

	// Build a serviceID -> *core.Pod index from the informer cache, keyed the
	// same way Branch A keys podsInKubernetesLocal (svc/node/pod/container). This
	// is what makes the predicate pod-scoped: each endpoint key resolves to
	// exactly its owning pod.
	podByServiceID := c.buildPodByServiceIDIndex()

	// Batched UID prefetch for the uid_mismatch guard: one prefix Get replaces a
	// synchronous per-key etcd read for every alive-pod key inside the catalog
	// Range. On error the UID guard is disabled for this pass (empty map) and the
	// IP guard still runs — fail-safe, never abort the whole pass.
	podUIDsByKey, err := c.adapterPrimary.GetEndpointsPodUIDs()
	if err != nil {
		log.Warn().Dict("custom_attributes", logger.Attrs().
			Str("runId", runID).
			Str("error", err.Error())).
			Msg("CleanFunc[BranchB]: batched pod-UID prefetch failed, UID guard disabled for this pass")
		podUIDsByKey = map[string]string{}
	}

	// seenStaleThisPass is shared across ALL entity passes and pruned exactly
	// once after the loop. It must NOT be per-entity: a key stale only in the
	// primary catalog would otherwise be pruned from firstSeenStale by the
	// secondary pass (which never sees it), restarting its grace forever.
	seenStaleThisPass := make(map[string]struct{})

	// deletedThisPass is likewise shared: a key the primary pass deleted must
	// not be re-observed by the secondary pass's snapshot catalog (the delete
	// fans out to both etcds inside the adapter), which would re-arm its grace
	// and log a spurious first-seen for a key that no longer exists.
	deletedThisPass := &branchBDeleted{keys: make(map[string]struct{})}

	entities := []struct {
		name    string
		catalog *sync.Map
	}{
		{"primary", c.addedEndpointsPrimary},
	}
	// Multi-entity: run the SAME per-IP prune against the secondary etcd
	// independently. If the secondary catalog is empty/unavailable this pass, it
	// simply finds nothing to prune; a secondary etcd outage never blocks the
	// primary reconcile (each entity is handled in its own loop iteration).
	if c.adapterPrimary.GetMultiEntityEnabled() {
		entities = append(entities, struct {
			name    string
			catalog *sync.Map
		}{"secondary", c.addedEndpointsSecondary})
	}

	for _, entity := range entities {
		c.reconcileStaleIPEndpointsForEntity(runID, entity.name, entity.catalog, podByServiceID, podUIDsByKey, seenStaleThisPass, deletedThisPass, podsInKubernetesLocal)
	}

	// Prune firstSeenStale of keys that recovered (not stale in ANY entity this
	// pass) so the leader-local map stays bounded. Done once here, after every
	// entity pass has recorded its sightings into the shared map.
	c.pruneFirstSeenStale(seenStaleThisPass)
}

// buildPodByServiceIDIndex builds serviceID -> *core.Pod from the pod informer
// cache, applying the same container filter the registration/Branch-A paths use
// so the keys line up with the etcd endpoint serviceIDs.
func (c *Controller) buildPodByServiceIDIndex() map[string]*core.Pod {
	index := make(map[string]*core.Pod)
	for _, obj := range c.podInformer.GetStore().List() {
		pod, ok := obj.(*core.Pod)
		if !ok {
			continue
		}
		podInfo := &PodInfo{}
		if err := podInfo.save(pod); err != nil {
			continue
		}
		lrcConfig := c.CheckLRCMatch(podInfo.Namespace, podInfo.Labels)
		filterPort := podInfo.annotatedPortToFilterOn(lrcConfig)
		for _, container := range podInfo.Containers {
			if container.Name == utils.EnvoyContainerName || container.Name == utils.NexusEnvoyContainerName || container.Name == utils.DbDriverContainerName {
				continue
			}
			if filterPort != 0 && !podInfo.declaresPort(container.Name, filterPort) {
				continue
			}
			for _, svc := range getServiceNameFromPod(podInfo, *c.k8sServices.Load(), lrcConfig) {
				serviceID := fmt.Sprintf("%s/%s/%s/%s", svc, podInfo.NodeName, podInfo.Name, container.Name)
				index[serviceID] = pod
			}
		}
	}
	return index
}

// staleIPCandidate is a key flagged for per-IP orphan deletion in this pass.
type staleIPCandidate struct {
	endpointKey string
	reason      string
	service     string
	// firstSeen orders candidates oldest-first when the safety fuse caps a
	// pass, so a standing backlog drains deterministically instead of wedging.
	firstSeen time.Time
}

// branchBDeleted tracks what the enforce loop removed during ONE Clean() pass,
// shared across entity passes. Without it the secondary pass re-Ranges its
// (snapshot) catalog, finds a key the primary pass just deleted, and re-arms
// its grace with a spurious first-seen INFO — and a pod_terminal prefix Delete
// removes sibling keys the later pass would likewise rediscover.
type branchBDeleted struct {
	keys map[string]struct{}
	// prefixes are container prefixes removed by pod_terminal prefix Deletes;
	// any key under one of them is gone from etcd even though a snapshot
	// catalog may still list it.
	prefixes []string
}

func (d *branchBDeleted) markKey(key string) { d.keys[key] = struct{}{} }

func (d *branchBDeleted) markPrefix(endpointKey string) {
	parts := strings.Split(endpointKey, "/")
	if len(parts) < 2 {
		return
	}
	d.prefixes = append(d.prefixes, strings.Join(parts[:len(parts)-2], "/"))
}

func (d *branchBDeleted) contains(endpointKey string) bool {
	if _, ok := d.keys[endpointKey]; ok {
		return true
	}
	for _, p := range d.prefixes {
		if strings.HasPrefix(endpointKey, p) {
			return true
		}
	}
	return false
}

// reconcileStaleIPEndpointsForEntity runs Branch B against one entity's etcd
// catalog. It is split from reconcileStaleIPEndpoints so the primary and each
// secondary etcd are pruned independently (a secondary failure cannot block the
// primary), and so the two-pass grace / fuse / mode logic lives in one place.
func (c *Controller) reconcileStaleIPEndpointsForEntity(
	runID, entity string,
	catalog *sync.Map,
	podByServiceID map[string]*core.Pod,
	podUIDsByKey map[string]string,
	seenStaleThisPass map[string]struct{},
	deletedThisPass *branchBDeleted,
	podsInKubernetesLocal map[string]bool,
) {
	now := time.Now()
	var ipMismatch, uidMismatch, podTerminalCount int
	candidates := make([]staleIPCandidate, 0)

	catalog.Range(func(key, _ any) bool {
		endpointKey, ok := key.(string)
		if !ok {
			return true
		}
		// Deleted by an earlier entity pass this Clean(): the adapter delete fans
		// out to both etcds, but this entity's catalog is a snapshot that may
		// still list the key. Skip before any observation so the drift metric is
		// not inflated and the grace window is not re-armed for a dead key.
		if deletedThisPass.contains(endpointKey) {
			return true
		}

		serviceID, err := utils.KeyToServiceID(endpointKey)
		if err != nil {
			return true
		}
		// Branch A (pod-gone) owns keys whose serviceID has no live pod. Branch B
		// only acts on keys whose owning pod STILL EXISTS.
		if _, alive := podsInKubernetesLocal[serviceID]; !alive {
